begin;
insert into auth.users(id,email) values ('00000000-0000-4000-8000-000000000021','recurring-test-a@example.invalid'),('00000000-0000-4000-8000-000000000022','recurring-test-b@example.invalid');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000021","role":"authenticated"}',true);
do $test$ declare card uuid;account uuid;key uuid:=gen_random_uuid();saved jsonb;again jsonb;draft jsonb;event uuid;rule uuid;batch uuid;count_before int;wb uuid;begin
insert into public.cards(name,issuer,closing,due) values('Cartão teste','Fictício',11,18) returning id into card;
insert into public.accounts(name) values('Conta teste') returning id into account;
draft:=jsonb_build_object('description','Receita única','kind','income','channel','cash','category','Outras receitas','amount_cents',100000,'date','2026-11-15','month','2026-11','mode','once','settled',true,'account_id',account);
saved:=public.save_financial_entry(key,draft);again:=public.save_financial_entry(key,draft);
if saved<>again or (select count(*) from public.cash_items)<>1 then raise exception 'Falha de idempotência';end if;
begin perform public.save_financial_entry(key,draft||'{"amount_cents":200000}'::jsonb);raise exception 'Reutilização alterada foi aceita';exception when others then if sqlerrm='Reutilização alterada foi aceita' then raise;end if;end;
draft:=jsonb_build_object('description','Streaming fictício','kind','expense','channel','card','category','Assinaturas','amount_cents',4000,'date','2026-11-15','month','2026-11','mode','monthly','card_id',card,'settled',false);
saved:=public.save_financial_entry(gen_random_uuid(),draft);
if (select count(*) from public.recurring_rules)<>1 then raise exception 'Recorrência não criada';end if;
draft:=draft||'{"description":"Compra parcelada fictícia","mode":"installment","installments":3,"amount_cents":10000}'::jsonb;
saved:=public.save_financial_entry(gen_random_uuid(),draft);
if not exists(select 1 from public.recurring_rules where id=(saved->>'id')::uuid and occurrence_count=3 and total_amount_cents=10000 and amount_cents=3333) then raise exception 'Parcela incorreta';end if;
draft:=jsonb_build_object('description','Mercado fictício','kind','expense','channel','card','category','Mercado','amount_cents',12000,'date','2026-11-15','month','2026-11','mode','once','card_id',card,'settled',true);
saved:=public.save_financial_entry(gen_random_uuid(),draft);event:=(saved->>'id')::uuid;
batch:=public.confirm_import_with_links(card,'2026-11','fixture-reconcile',12000,jsonb_build_array(jsonb_build_object('date','2026-11-15','description','Mercado fictício','amount',12000,'kind','compra','current',1,'total',1,'category','Mercado','match_type','event','match_id',event)));
if (select count(*) from public.entry_matches where event_id=event)<>1 then raise exception 'Compra não conciliada';end if;
count_before:=(select count(*) from public.imports);
begin perform public.confirm_import_with_links(card,'2026-12','fixture-invalid-link',12000,jsonb_build_array(jsonb_build_object('date','2026-12-15','description','Outra compra fictícia','amount',12000,'kind','compra','current',1,'total',1,'category','Mercado','match_type','event','match_id',event)));raise exception 'Vínculo inválido aceito';exception when others then if sqlerrm='Vínculo inválido aceito' then raise;end if;end;
if (select count(*) from public.imports)<>count_before then raise exception 'Importação parcial foi gravada';end if;
delete from public.imports where id=batch;
if exists(select 1 from public.entry_matches where event_id=event) or not exists(select 1 from public.card_events where id=event) then raise exception 'Desfazer apagou compra ou manteve vínculo';end if;
batch:=public.confirm_import_with_links(card,'2026-11','fixture-future-installments',12345,jsonb_build_array(jsonb_build_object('date','2026-10-02','description','LOJA FICTICIA (Parcela 02 de 05)','amount',12345,'kind','compra','current',2,'total',5,'category','Compras','future_mode','installment','future_description','LOJA FICTICIA')));
if not exists(select 1 from public.recurring_rules where source_import_id=batch and occurrence_count=3 and first_installment=3 and total_installments=5 and start_month='2026-12') then raise exception 'Parcelas futuras da fatura não criadas';end if;
delete from public.imports where id=batch;
if exists(select 1 from public.recurring_rules where source_import_id=batch) then raise exception 'Desfazer não removeu projeções da importação';end if;
draft:=jsonb_build_object('description','Salário previsto fictício','kind','income','channel','cash','category','Salário','amount_cents',500000,'date','2026-11-15','month','2026-11','mode','monthly','account_id',account,'settled',false);
saved:=public.save_financial_entry(gen_random_uuid(),draft);rule:=(saved->>'id')::uuid;
draft:=draft||jsonb_build_object('mode','once','fulfill_rule_id',rule,'amount_cents',510000,'settled',true);
perform public.save_financial_entry(gen_random_uuid(),draft);
if (select count(*) from public.cash_items)<>1 or not exists(select 1 from public.recurrence_states where rule_id=rule and month='2026-11' and status='realized' and amount_override_cents=510000) then raise exception 'Recebimento duplicou receita';end if;
wb:=public.import_workbook_plan('fixture-workbook',jsonb_build_array(jsonb_build_object('description','Conta da planilha fictícia','kind','expense','channel','cash','category','Outros','amount_cents',5000,'start_month','2026-11','end_month','2026-12','due_day',15,'account_id',account,'settled_months',jsonb_build_array('2026-11'))),'[{"month":"2026-11","savings_target_cents":10000}]',false);
if (select count(*) from public.workbook_imports)<>1 then raise exception 'Planilha não gravada';end if;
begin perform public.import_workbook_plan('fixture-workbook','[]','[]',false);raise exception 'Planilha duplicada aceita';exception when others then if sqlerrm='Planilha duplicada aceita' then raise;end if;end;
perform set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000022","role":"authenticated"}',true);
if exists(select 1 from public.accounts) or exists(select 1 from public.recurring_rules) or exists(select 1 from public.card_events) or exists(select 1 from public.action_requests) then raise exception 'Vazamento entre usuários';end if;
begin perform public.save_financial_entry(gen_random_uuid(),jsonb_build_object('description','Invasão de conta fictícia','kind','expense','channel','cash','category','Outros','amount_cents',100,'date','2026-11-15','month','2026-11','mode','once','account_id',account));raise exception 'Conta de outro usuário aceita';exception when foreign_key_violation then null;end;
end $test$;
rollback;
select 'Idempotência, recorrência, parcelas, recebimento, conciliação atômica, desfazer, planilha e isolamento validados; fixtures revertidas' as result;
